/// <summary>
///MPJ_28155_SalesFinalisation Service class 
/// </summary>
class METSalesOrderShipmentWorkbenchRouteUpdateService extends SysOperationServiceBase
{
    #OCCRetryCount

   
    METSalesOrderShipmentWorkbenchRouteUpdateContract    dataContract;
    BatchHeader                                          batchHeader;
    SalesId                                              salesId;


   
}

Method.Source:
    /// <summary>
    /// processing logic
    /// </summary>
    /// <param name = "_dataContract">The data contract</param>
    public void process(METSalesOrderShipmentWorkbenchRouteUpdateContract _dataContract)
    {
        dataContract = _dataContract;
        SalesTable       salesTable;

         
        int recordCount;
        try
        {
            ttsbegin;
            for(recordCount = 1; recordCount <= conLen(dataContract.parmSalesOrderList()); recordCount++)
            {
                salesId    = conPeek(dataContract.parmSalesOrderList(),recordCount);
                select forupdate firstonly salesTable where salesTable.SalesId == salesId;
                salesTable.METRoute     = dataContract.parmPrimaryRouteChange();
                salesTable.METRouteStopNum = dataContract.parmRouteStopChange();
                salesTable.update();
           
            }
            ttscommit;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() != 0)
            {
                throw Exception::UpdateConflict;
            }
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            retry;
        }
      
    }
